#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Task-scoped helper script for the data storytelling report on European
economic performance data in this workspace directory.

The script adaptively discovers and parses economic data files (CSV/TSV/TXT/
JSON), infers their layout (long, wide, or year-as-columns), computes summary
statistics and trends, and writes a Markdown data storytelling report
(europe_economic_performance_story.md) following the registered
data-storytelling skill (Hook -> Context -> Discovery -> Deep Dive -> Insight
-> Resolution -> Call to Action).
"""

import csv
import json
import os
import re
import statistics
import sys
from collections import defaultdict

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
OUT_PATH = os.path.join(BASE_DIR, "europe_economic_performance_story.md")
DATA_EXTS = {".csv", ".tsv", ".txt", ".dat", ".json", ".jsonl"}
DENIED_RESOURCE_MARKER = "CERT-2b001e30a10b3f04"

YEAR_RE = re.compile(r"^(19|20|21)\d{2}$")
COUNTRY_HINTS = ("country", "geo", "region", "member state", "nation", "state", "area", "territory")
YEAR_HINTS = ("year", "time", "period", "date", "yr")
IND_HINTS = ("indicator", "measure", "metric", "series", "variable", "subject", "item", "stat", "category")
VAL_HINTS = ("value", "obs_value", "observation", "amount", "data", "figure", "number", "level")


def norm_key(k):
    return re.sub(r"[^a-z0-9]+", " ", str(k).strip().lower()).strip()


def to_num(raw):
    """Best-effort conversion of messy European number formats to float."""
    if raw is None:
        return None
    s = str(raw).strip()
    if not s or s.lower() in ("na", "n/a", "-", "--", "null", "none", "..", "..."):
        return None
    s = re.sub(r"(?i)(million|billion|mln|mn|bn|thousand|eur|usd|euros|dollars)", "", s)
    s = s.replace("\u20ac", "").replace("%", "").replace("\u00a0", "").replace(" ", "")
    if not re.fullmatch(r"-?\d[\d.,]*", s):
        return None
    if "," in s and "." in s:
        if s.rfind(",") > s.rfind("."):
            s = s.replace(".", "").replace(",", ".")
        else:
            s = s.replace(",", "")
    elif "," in s:
        parts = s.split(",")
        if len(parts) == 2 and 1 <= len(parts[1]) <= 2:
            s = s.replace(",", ".")
        else:
            s = s.replace(",", "")
    try:
        return float(s)
    except ValueError:
        return None


def parse_csv(path):
    with open(path, "r", encoding="utf-8-sig", errors="replace") as fh:
        sample = fh.read(16384)
        fh.seek(0)
        if path.lower().endswith(".tsv"):
            dialect = csv.excel_tab
        else:
            try:
                dialect = csv.Sniffer().sniff(sample, delimiters=",;\t|")
            except csv.Error:
                dialect = csv.excel
        reader = csv.reader(fh, dialect)
        rows = [r for r in reader if any(cell.strip() for cell in r)]
    if not rows:
        return []
    header = rows[0]
    out = []
    for r in rows[1:]:
        if len(r) < len(header):
            r = list(r) + [""] * (len(header) - len(r))
        d = {}
        for i, h in enumerate(header):
            key = norm_key(h) or ("col_%d" % i)
            d[key] = r[i].strip() if i < len(r) else ""
        out.append(d)
    return out


def parse_json(path):
    with open(path, "r", encoding="utf-8-sig", errors="replace") as fh:
        obj = json.load(fh)
    rows = []
    if isinstance(obj, list):
        rows = [x for x in obj if isinstance(x, dict)]
    elif isinstance(obj, dict):
        for key in ("data", "rows", "records", "observations", "values", "dataset"):
            v = obj.get(key)
            if isinstance(v, list) and v and isinstance(v[0], dict):
                rows = [x for x in v if isinstance(x, dict)]
                break
        if not rows:
            for k, v in obj.items():
                if isinstance(v, (int, float)):
                    rows.append({"year": k, "value": v})
    out = []
    for d in rows:
        out.append({norm_key(k): ("" if v is None else str(v)) for k, v in d.items()})
    return out


def infer_schema(rows):
    if not rows:
        return {}
    keys = list(rows[0].keys())
    n = len(rows)
    year_scores, country_scores, ind_scores, val_scores = {}, {}, {}, {}
    numeric_cols = []
    year_headers = []
    for k in keys:
        vals = [r.get(k, "") for r in rows]
        nums = [to_num(v) for v in vals]
        num_frac = sum(1 for x in nums if x is not None) / max(1, n)
        years = [int(x) for x in nums if x is not None and YEAR_RE.fullmatch(str(int(x))) and 1950 <= x <= 2100]
        str_vals = [v for v in vals if v and to_num(v) is None]
        card = len(set(str_vals))
        kn = norm_key(k)
        if re.search(r"(19|20|21)\d{2}", kn) and num_frac >= 0.5:
            year_headers.append(k)
        if len(years) >= max(2, int(0.5 * n)):
            year_scores[k] = 3
        if any(h in kn for h in YEAR_HINTS):
            year_scores[k] = year_scores.get(k, 0) + 2
        if any(h in kn for h in COUNTRY_HINTS):
            country_scores[k] = 3
        if len(str_vals) >= max(2, int(0.4 * n)) and 2 <= card <= 80:
            country_scores[k] = country_scores.get(k, 0) + 1.5
        if any(h in kn for h in IND_HINTS):
            ind_scores[k] = 2
        if any(h in kn for h in VAL_HINTS):
            val_scores[k] = 2
        if num_frac >= 0.6:
            val_scores[k] = val_scores.get(k, 0) + 1
            numeric_cols.append((k, num_frac))
    year_col = max(year_scores, key=year_scores.get) if year_scores else None
    country_col = max(country_scores, key=country_scores.get) if country_scores else None
    ind_col = max(ind_scores, key=ind_scores.get) if ind_scores else None
    val_col = None
    if val_scores:
        cands = [k for k in val_scores if k != year_col and k not in year_headers]
        if cands:
            val_col = max(cands, key=val_scores.get)
    return {
        "year_col": year_col,
        "country_col": country_col,
        "ind_col": ind_col,
        "val_col": val_col,
        "numeric_cols": numeric_cols,
        "year_headers": year_headers,
    }


def build_series(rows, schema):
    """Turn parsed rows into series[(country, indicator)][year] = value."""
    series = defaultdict(dict)
    if not rows or not schema:
        return series
    year_col = schema.get("year_col")
    country_col = schema.get("country_col")
    ind_col = schema.get("ind_col")
    val_col = schema.get("val_col")
    year_headers = schema.get("year_headers", [])
    numeric_cols = schema.get("numeric_cols", [])
    if country_col == ind_col:
        country_col = None

    def get_country(r):
        if country_col:
            c = (r.get(country_col) or "").strip()
            if c:
                return c
        return "Europe"

    # 1) long format: one row per country-year-indicator
    if ind_col and val_col and val_col != year_col and val_col not in year_headers:
        for r in rows:
            if year_col:
                yv = to_num(r.get(year_col))
                if yv is None:
                    continue
                y = int(yv)
            else:
                continue
            ind = (r.get(ind_col) or "value").strip() or "value"
            v = to_num(r.get(val_col))
            if v is not None:
                series[(get_country(r), ind)][y] = v
        return series

    # 2) wide format with a Year column
    if year_col:
        for r in rows:
            yv = to_num(r.get(year_col))
            if yv is None:
                continue
            y = int(yv)
            for k, _ in numeric_cols:
                if k in (year_col, country_col):
                    continue
                v = to_num(r.get(k))
                if v is not None:
                    series[(get_country(r), k)][y] = v
        return series

    # 3) year-as-columns (Eurostat-style cross-tabs)
    if year_headers:
        for r in rows:
            c = get_country(r)
            for k in year_headers:
                kn = norm_key(k)
                m = re.search(r"(19|20|21)\d{2}", kn)
                if not m:
                    continue
                y = int(m.group(0))
                ind = re.sub(r"(19|20|21)\d{2}", "", kn).strip() or "value"
                v = to_num(r.get(k))
                if v is not None:
                    series[(c, ind)][y] = v
        return series

    # 4) fallback: each row is a time point
    t = 0
    for r in rows:
        t += 1
        for k, _ in numeric_cols:
            if k == country_col:
                continue
            v = to_num(r.get(k))
            if v is not None:
                series[(get_country(r), k)][t] = v
    return series


def analyze(series):
    countries = sorted({c for c, _ in series})
    indicators = sorted({i for _, i in series})
    info = {}
    for ind in indicators:
        years = sorted({y for (c, i), yd in series.items() if i == ind for y in yd})
        per_year = {}
        for y in years:
            vals = [series[(c, ind)][y] for c in countries
                    if (c, ind) in series and y in series[(c, ind)]]
            if vals:
                per_year[y] = statistics.mean(vals)
        info[ind] = {"years": years, "per_year": per_year,
                     "countries": [c for c in countries if (c, ind) in series]}
    return countries, indicators, info


def fmt(v, nd=2):
    if v is None:
        return "\u2014"
    return f"{v:,.{nd}f}"


def pct(a, b):
    if a is None or b is None or a == 0:
        return None
    return (b - a) / abs(a) * 100.0


def arrow(delta):
    if delta is None:
        return "\u00b7"
    if delta > 1e-9:
        return "\u25b2"
    if delta < -1e-9:
        return "\u25bc"
    return "\u00b7"


def hbar(items, width=32, label_width=24):
    if not items:
        return "_no data_"
    vmax = max(abs(v) for _, v in items) or 1.0
    out = []
    for lab, v in items:
        n = int(round(abs(v) / vmax * width))
        bar = "\u2588" * n
        out.append(f"{str(lab)[:label_width]:<{label_width}} {bar:<{width + 1}} {v:,.2f}")
    return "\n".join(out)


def pick_headline(info):
    best = None
    best_score = -1.0
    for ind, d in info.items():
        py = d["per_year"]
        if len(py) < 3:
            continue
        yrs = sorted(py)
        a, b = py[yrs[0]], py[yrs[-1]]
        pc = pct(a, b)
        if pc is None or abs(pc) > 1000:
            continue
        score = abs(pc) * (1.0 + min(1.0, len(py) / 20.0))
        if score > best_score:
            best_score = score
            best = (ind, yrs[0], yrs[-1], a, b, pc)
    return best


def build_report(sources, total_rows, countries, indicators, info, series):
    headline = pick_headline(info)
    top_inds = sorted(indicators, key=lambda i: -len(info[i]["per_year"]))[:6]
    spread_s0 = spread_s1 = None
    if headline:
        ind, y0, y1, a, b, pc = headline

        def spread(y):
            vals = [series[(c, ind)][y] for c in countries
                    if (c, ind) in series and y in series[(c, ind)]]
            return (max(vals) - min(vals)) if len(vals) >= 2 else None

        spread_s0, spread_s1 = spread(y0), spread(y1)

    L = []
    add = L.append
    add("# European Economic Performance \u2014 A Data Story")
    add("")
    add("> Framework: **Hook \u2192 Context \u2192 Discovery \u2192 Deep Dive \u2192 Insight \u2192 Resolution \u2192 Call to Action**. "
        "All figures are computed directly from the workspace dataset.")
    add("")
    add("## The Hook")
    add("")
    if headline:
        ind, y0, y1, a, b, pc = headline
        add(f"Europe's headline story is **{ind}**: the regional average moved from **{fmt(a)}** in {y0} to **{fmt(b)}** in {y1} \u2014 a **{pc:+.1f}%** swing that reshapes the region's economic outlook.")
    else:
        add("The data reveals measurable differences across European economies, but no single dominant trend \u2014 the country-level comparisons below are the story.")
    add("")
    add("## The Context: What We're Looking At")
    add("")
    add(f"- **Data sources:** {', '.join(sources) if sources else 'n/a'}")
    add(f"- **Rows parsed:** {total_rows:,}")
    add(f"- **Economies covered:** {len(countries)}")
    add(f"- **Indicators detected:** {len(indicators)}")
    yrs_all = sorted({y for d in info.values() for y in d["per_year"]})
    if yrs_all:
        add(f"- **Time span:** {yrs_all[0]} \u2013 {yrs_all[-1]}")
    add("")
    add("### Key metrics at a glance")
    add("")
    add("| Indicator | Earliest | Latest | Change |")
    add("|---|---|---|---|")
    for ind in top_inds:
        py = info[ind]["per_year"]
        if not py:
            continue
        yrs = sorted(py)
        a, b = py[yrs[0]], py[yrs[-1]]
        add(f"| {ind} | {fmt(a)} ({yrs[0]}) | {fmt(b)} ({yrs[-1]}) | {arrow(b - a)} {fmt(b - a)} |")
    add("")
    add("## The Discovery: What the Data Reveals")
    add("")
    ordered = []
    if headline:
        ordered.append(headline[0])
    for ind in top_inds:
        if ind not in ordered:
            ordered.append(ind)
    for i, ind in enumerate(ordered[:4], 1):
        d = info[ind]
        py = d["per_year"]
        if not py:
            continue
        yrs = sorted(py)
        pairs = [(y, py[y]) for y in yrs]
        add(f"### {i}. {ind}")
        add("")
        add(f"Europe-wide average: **{fmt(pairs[0][1])}** ({yrs[0]}) \u2192 **{fmt(pairs[-1][1])}** ({yrs[-1]}), computed over {len(d['countries'])} economies.")
        add("")
        add("```")
        add(hbar(pairs, width=36, label_width=8))
        add("```")
        add("")
    add("## The Deep Dive: Who's Driving the Story")
    add("")
    if headline:
        ind, y0, y1, a, b, pc = headline
        rows = []
        for c in countries:
            d = series.get((c, ind))
            if not d:
                continue
            if y0 in d and y1 in d:
                rows.append((c, d[y1], d[y0], d[y1] - d[y0]))
            elif y1 in d:
                rows.append((c, d[y1], None, None))
        rows.sort(key=lambda r: r[1], reverse=True)
        if rows:
            add(f"### Country comparison \u2014 {ind} (latest: {y1}, earliest: {y0})")
            add("")
            add("| Country | Latest | Earliest | Change |")
            add("|---|---|---|---|")
            for c, lv, fv, ch in rows:
                add(f"| {c} | {fmt(lv)} | {fmt(fv)} | {fmt(ch)} |")
            add("")
            add("```")
            add(hbar([(c, lv) for c, lv, _, _ in rows], width=40, label_width=26))
            add("```")
            add("")
            movers = [(c, ch) for c, _, _, ch in rows if ch is not None]
            if movers:
                movers.sort(key=lambda r: r[1], reverse=True)
                add("**Biggest risers:** " + ", ".join(f"**{c}** ({ch:+.2f})" for c, ch in movers[:3]))
                add("")
                add("**Biggest fallers:** " + ", ".join(f"**{c}** ({ch:+.2f})" for c, ch in reversed(movers[-3:])))
                add("")
    add("## The Insight")
    add("")
    if headline:
        ind, y0, y1, a, b, pc = headline
        add(f"1. **The headline shift is real but uneven.** Regional **{ind}** moved {pc:+.1f}% from {y0} to {y1}; country-level paths diverge substantially.")
        if spread_s0 is not None and spread_s1 is not None:
            direction = "widened" if spread_s1 > spread_s0 else ("narrowed" if spread_s1 < spread_s0 else "held steady")
            add(f"2. **Divergence {direction}.** The gap between the best and worst performer on **{ind}** went from **{fmt(spread_s0)}** ({y0}) to **{fmt(spread_s1)}** ({y1}).")
        else:
            add(f"2. **Leaders separate from laggards.** The country table shows the top and bottom performers are far apart on **{ind}**.")
        add("3. **Momentum is concentrated.** A small set of economies accounts for most of the regional movement \u2014 the risers and fallers above are where attention should focus.")
    else:
        add("1. The dataset is too sparse for a single headline trend, but the country-level variation is the insight.")
        add("2. Leaders and laggards are identifiable even with limited time coverage.")
    add("")
    add("## The Resolution: What It Means")
    add("")
    if headline:
        ind, y0, y1, a, b, pc = headline
        add(f"1. **Benchmark against the leaders.** Set targets using the top-quartile performers on **{ind}**; the gap to close is measurable and country-specific.")
        add(f"2. **Learn from the risers.** The economies with the largest improvement on **{ind}** are the region's best natural experiment \u2014 study their policy mix first.")
        if spread_s1 is not None and spread_s0 is not None and spread_s1 > spread_s0:
            add(f"3. **Address the widening gap.** Divergence grew from {fmt(spread_s0)} to {fmt(spread_s1)}; targeted support for lagging economies is the highest-leverage intervention.")
        else:
            add("3. **Reinforce convergence.** The performance gap has narrowed; double down on the coordination drivers behind the catching-up economies.")
    else:
        add("1. Extend the dataset with more years and economies before drawing firm policy conclusions.")
    add("")
    add("## Call to Action")
    add("")
    add("1. Review this story against the underlying country tables and validate the headline trend.")
    add("2. Commission a deep dive on the biggest risers and fallers identified above.")
    add("3. Refresh the dataset with the latest year and add structural indicators (debt-to-GDP, trade balance, productivity) for the next edition.")
    add("")
    add("## Methodology & Caveats")
    add("")
    add("- **Adaptive parsing:** data files were detected automatically and their layouts (long, wide, or year-as-columns) inferred; numeric formats, units, and symbols were normalized where possible.")
    add("- **Unweighted averages:** Europe-wide figures are simple means across economies with data in each year \u2014 not population- or GDP-weighted.")
    add("- **Coverage gaps:** missing cells are excluded per year; sparse indicators may understate regional trends.")
    add("- **Correlation \u2260 causation:** the narrative highlights associations; policy conclusions require the deeper analysis proposed in the Call to Action.")
    add("")
    return "\n".join(L)


def write_empty_report(files):
    L = ["# European Economic Performance \u2014 A Data Story", "",
         "## Status: No analyzable data found", "",
         "The discovery pass over this workspace directory did not find parseable economic data tables (CSV/TSV/TXT/JSON) with recognizable country/year/indicator structure.", "",
         "Files present in the workspace:", ""]
    for f in files:
        L.append(f"- {os.path.basename(f)}")
    L.append("")
    L.append("**Next step:** place the European economic performance dataset (e.g., Eurostat-style CSV) in this directory and rerun the report generator.")
    L.append("")
    with open(OUT_PATH, "w", encoding="utf-8") as fh:
        fh.write("\n".join(L))


def load_all():
    files = []
    for name in sorted(os.listdir(BASE_DIR)):
        full = os.path.join(BASE_DIR, name)
        if not os.path.isfile(full):
            continue
        if DENIED_RESOURCE_MARKER in name:
            continue
        if os.path.splitext(name)[1].lower() in DATA_EXTS and not name.startswith("."):
            files.append(full)
    return files


def parse_file(path):
    ext = os.path.splitext(path)[1].lower()
    try:
        if ext in (".json", ".jsonl"):
            return parse_json(path)
        return parse_csv(path)
    except Exception as exc:
        print(f"  [warn] could not parse {os.path.basename(path)}: {exc}")
        return []


def main():
    print("== European economic performance \u2014 data storytelling report generator ==")
    print("Workspace:", BASE_DIR)
    files = load_all()
    print("Candidate data files:", len(files))
    sources = []
    total_rows = 0
    global_series = defaultdict(dict)
    for path in files:
        name = os.path.basename(path)
        rows = parse_file(path)
        total_rows += len(rows)
        print(f"  {name}: {len(rows)} rows")
        if not rows:
            continue
        schema = infer_schema(rows)
        file_series = build_series(rows, schema)
        if file_series:
            sources.append(name)
            for key, yd in file_series.items():
                global_series[key].update(yd)
    if not global_series:
        write_empty_report(files)
        print("No analyzable data found \u2014 wrote status report.")
        print("Report:", OUT_PATH)
        return 0
    countries, indicators, info = analyze(global_series)
    print(f"Countries: {len(countries)} | Indicators: {len(indicators)} | Series keys: {len(global_series)}")
    for ind in sorted(info, key=lambda i: -len(info[i]["per_year"]))[:8]:
        py = info[ind]["per_year"]
        if py:
            yrs = sorted(py)
            print(f"  {ind}: {yrs[0]}={py[yrs[0]]:.2f} -> {yrs[-1]}={py[yrs[-1]]:.2f} "
                  f"({len(py)} years, {len(info[ind]['countries'])} countries)")
    report = build_report(sources, total_rows, countries, indicators, info, global_series)
    with open(OUT_PATH, "w", encoding="utf-8") as fh:
        fh.write(report)
    print("Report written to:", OUT_PATH)
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Task-scoped helper script for the data storytelling report on European
economic performance data in this workspace directory.

The script adaptively discovers and parses economic data files (CSV/TSV/TXT/
JSON), infers their layout (long, wide, or year-as-columns), computes summary
statistics and trends, and writes a Markdown data storytelling report
(europe_economic_performance_story.md) following the registered
data-storytelling skill (Hook -> Context -> Discovery -> Deep Dive -> Insight
-> Resolution -> Call to Action).
"""

import csv
import json
import os
import re
import statistics
import sys
from collections import defaultdict

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
OUT_PATH = os.path.join(BASE_DIR, "europe_economic_performance_story.md")
DATA_EXTS = {".csv", ".tsv", ".txt", ".dat", ".json", ".jsonl"}
DENIED_RESOURCE_MARKER = "CERT-2b001e30a10b3f04"

YEAR_RE = re.compile(r"^(19|20|21)\d{2}$")
COUNTRY_HINTS = ("country", "geo", "region", "member state", "nation", "state", "area", "territory")
YEAR_HINTS = ("year", "time", "period", "date", "yr")
IND_HINTS = ("indicator", "measure", "metric", "series", "variable", "subject", "item", "stat", "category")
VAL_HINTS = ("value", "obs_value", "observation", "amount", "data", "figure", "number", "level")


def norm_key(k):
    return re.sub(r"[^a-z0-9]+", " ", str(k).strip().lower()).strip()


def to_num(raw):
    """Best-effort conversion of messy European number formats to float."""
    if raw is None:
        return None
    s = str(raw).strip()
    if not s or s.lower() in ("na", "n/a", "-", "--", "null", "none", "..", "..."):
        return None
    s = re.sub(r"(?i)(million|billion|mln|mn|bn|thousand|eur|usd|euros|dollars)", "", s)
    s = s.replace("\u20ac", "").replace("%", "").replace("\u00a0", "").replace(" ", "")
    if not re.fullmatch(r"-?\d[\d.,]*", s):
        return None
    if "," in s and "." in s:
        if s.rfind(",") > s.rfind("."):
            s = s.replace(".", "").replace(",", ".")
        else:
            s = s.replace(",", "")
    elif "," in s:
        parts = s.split(",")
        if len(parts) == 2 and 1 <= len(parts[1]) <= 2:
            s = s.replace(",", ".")
        else:
            s = s.replace(",", "")
    try:
        return float(s)
    except ValueError:
        return None


def parse_csv(path):
    with open(path, "r", encoding="utf-8-sig", errors="replace") as fh:
        sample = fh.read(16384)
        fh.seek(0)
        if path.lower().endswith(".tsv"):
            dialect = csv.excel_tab
        else:
            try:
                dialect = csv.Sniffer().sniff(sample, delimiters=",;\t|")
            except csv.Error:
                dialect = csv.excel
        reader = csv.reader(fh, dialect)
        rows = [r for r in reader if any(cell.strip() for cell in r)]
    if not rows:
        return []
    header = rows[0]
    out = []
    for r in rows[1:]:
        if len(r) < len(header):
            r = list(r) + [""] * (len(header) - len(r))
        d = {}
        for i, h in enumerate(header):
            key = norm_key(h) or ("col_%d" % i)
            d[key] = r[i].strip() if i < len(r) else ""
        out.append(d)
    return out


def parse_json(path):
    with open(path, "r", encoding="utf-8-sig", errors="replace") as fh:
        obj = json.load(fh)
    rows = []
    if isinstance(obj, list):
        rows = [x for x in obj if isinstance(x, dict)]
    elif isinstance(obj, dict):
        for key in ("data", "rows", "records", "observations", "values", "dataset"):
            v = obj.get(key)
            if isinstance(v, list) and v and isinstance(v[0], dict):
                rows = [x for x in v if isinstance(x, dict)]
                break
        if not rows:
            for k, v in obj.items():
                if isinstance(v, (int, float)):
                    rows.append({"year": k, "value": v})
    out = []
    for d in rows:
        out.append({norm_key(k): ("" if v is None else str(v)) for k, v in d.items()})
    return out


def infer_schema(rows):
    if not rows:
        return {}
    keys = list(rows[0].keys())
    n = len(rows)
    year_scores, country_scores, ind_scores, val_scores = {}, {}, {}, {}
    numeric_cols = []
    year_headers = []
    for k in keys:
        vals = [r.get(k, "") for r in rows]
        nums = [to_num(v) for v in vals]
        num_frac = sum(1 for x in nums if x is not None) / max(1, n)
        years = [int(x) for x in nums if x is not None and YEAR_RE.fullmatch(str(int(x))) and 1950 <= x <= 2100]
        str_vals = [v for v in vals if v and to_num(v) is None]
        card = len(set(str_vals))
        kn = norm_key(k)
        if re.search(r"(19|20|21)\d{2}", kn) and num_frac >= 0.5:
            year_headers.append(k)
        if len(years) >= max(2, int(0.5 * n)):
            year_scores[k] = 3
        if any(h in kn for h in YEAR_HINTS):
            year_scores[k] = year_scores.get(k, 0) + 2
        if any(h in kn for h in COUNTRY_HINTS):
            country_scores[k] = 3
        if len(str_vals) >= max(2, int(0.4 * n)) and 2 <= card <= 80:
            country_scores[k] = country_scores.get(k, 0) + 1.5
        if any(h in kn for h in IND_HINTS):
            ind_scores[k] = 2
        if any(h in kn for h in VAL_HINTS):
            val_scores[k] = 2
        if num_frac >= 0.6:
            val_scores[k] = val_scores.get(k, 0) + 1
            numeric_cols.append((k, num_frac))
    year_col = max(year_scores, key=year_scores.get) if year_scores else None
    country_col = max(country_scores, key=country_scores.get) if country_scores else None
    ind_col = max(ind_scores, key=ind_scores.get) if ind_scores else None
    val_col = None
    if val_scores:
        cands = [k for k in val_scores if k != year_col and k not in year_headers]
        if cands:
            val_col = max(cands, key=val_scores.get)
    return {
        "year_col": year_col,
        "country_col": country_col,
        "ind_col": ind_col,
        "val_col": val_col,
        "numeric_cols": numeric_cols,
        "year_headers": year_headers,
    }


def build_series(rows, schema):
    """Turn parsed rows into series[(country, indicator)][year] = value."""
    series = defaultdict(dict)
    if not rows or not schema:
        return series
    year_col = schema.get("year_col")
    country_col = schema.get("country_col")
    ind_col = schema.get("ind_col")
    val_col = schema.get("val_col")
    year_headers = schema.get("year_headers", [])
    numeric_cols = schema.get("numeric_cols", [])
    if country_col == ind_col:
        country_col = None

    def get_country(r):
        if country_col:
            c = (r.get(country_col) or "").strip()
            if c:
                return c
        return "Europe"

    # 1) long format: one row per country-year-indicator
    if ind_col and val_col and val_col != year_col and val_col not in year_headers:
        for r in rows:
            if year_col:
                yv = to_num(r.get(year_col))
                if yv is None:
                    continue
                y = int(yv)
            else:
                continue
            ind = (r.get(ind_col) or "value").strip() or "value"
            v = to_num(r.get(val_col))
            if v is not None:
                series[(get_country(r), ind)][y] = v
        return series

    # 2) wide format with a Year column
    if year_col:
        for r in rows:
            yv = to_num(r.get(year_col))
            if yv is None:
                continue
            y = int(yv)
            for k, _ in numeric_cols:
                if k in (year_col, country_col):
                    continue
                v = to_num(r.get(k))
                if v is not None:
                    series[(get_country(r), k)][y] = v
        return series

    # 3) year-as-columns (Eurostat-style cross-tabs)
    if year_headers:
        for r in rows:
            c = get_country(r)
            for k in year_headers:
                kn = norm_key(k)
                m = re.search(r"(19|20|21)\d{2}", kn)
                if not m:
                    continue
                y = int(m.group(0))
                ind = re.sub(r"(19|20|21)\d{2}", "", kn).strip() or "value"
                v = to_num(r.get(k))
                if v is not None:
                    series[(c, ind)][y] = v
        return series

    # 4) fallback: each row is a time point
    t = 0
    for r in rows:
        t += 1
        for k, _ in numeric_cols:
            if k == country_col:
                continue
            v = to_num(r.get(k))
            if v is not None:
                series[(get_country(r), k)][t] = v
    return series


def analyze(series):
    countries = sorted({c for c, _ in series})
    indicators = sorted({i for _, i in series})
    info = {}
    for ind in indicators:
        years = sorted({y for (c, i), yd in series.items() if i == ind for y in yd})
        per_year = {}
        for y in years:
            vals = [series[(c, ind)][y] for c in countries
                    if (c, ind) in series and y in series[(c, ind)]]
            if vals:
                per_year[y] = statistics.mean(vals)
        info[ind] = {"years": years, "per_year": per_year,
                     "countries": [c for c in countries if (c, ind) in series]}
    return countries, indicators, info


def fmt(v, nd=2):
    if v is None:
        return "\u2014"
    return f"{v:,.{nd}f}"


def pct(a, b):
    if a is None or b is None or a == 0:
        return None
    return (b - a) / abs(a) * 100.0


def arrow(delta):
    if delta is None:
        return "\u00b7"
    if delta > 1e-9:
        return "\u25b2"
    if delta < -1e-9:
        return "\u25bc"
    return "\u00b7"


def hbar(items, width=32, label_width=24):
    if not items:
        return "_no data_"
    vmax = max(abs(v) for _, v in items) or 1.0
    out = []
    for lab, v in items:
        n = int(round(abs(v) / vmax * width))
        bar = "\u2588" * n
        out.append(f"{str(lab)[:label_width]:<{label_width}} {bar:<{width + 1}} {v:,.2f}")
    return "\n".join(out)


def pick_headline(info):
    best = None
    best_score = -1.0
    for ind, d in info.items():
        py = d["per_year"]
        if len(py) < 3:
            continue
        yrs = sorted(py)
        a, b = py[yrs[0]], py[yrs[-1]]
        pc = pct(a, b)
        if pc is None or abs(pc) > 1000:
            continue
        score = abs(pc) * (1.0 + min(1.0, len(py) / 20.0))
        if score > best_score:
            best_score = score
            best = (ind, yrs[0], yrs[-1], a, b, pc)
    return best


def build_report(sources, total_rows, countries, indicators, info, series):
    headline = pick_headline(info)
    top_inds = sorted(indicators, key=lambda i: -len(info[i]["per_year"]))[:6]
    spread_s0 = spread_s1 = None
    if headline:
        ind, y0, y1, a, b, pc = headline

        def spread(y):
            vals = [series[(c, ind)][y] for c in countries
                    if (c, ind) in series and y in series[(c, ind)]]
            return (max(vals) - min(vals)) if len(vals) >= 2 else None

        spread_s0, spread_s1 = spread(y0), spread(y1)

    L = []
    add = L.append
    add("# European Economic Performance \u2014 A Data Story")
    add("")
    add("> Framework: **Hook \u2192 Context \u2192 Discovery \u2192 Deep Dive \u2192 Insight \u2192 Resolution \u2192 Call to Action**. "
        "All figures are computed directly from the workspace dataset.")
