    add("## The Hook")
    add("")
    if headline:
        ind, y0, y1, a, b, pc = headline
        add(f"Europe's headline story is **{ind}**: the regional average moved from **{fmt(a)}** in {y0} to **{fmt(b)}** in {y1} \u2014 a **{pc:+.1f}%** swing that reshapes the region's economic outlook.")
    else:
        add("The data reveals measurable differences across European economies, but no single dominant trend \u2014 the country-level comparisons below are the story.")
    add("")
    add("## The Context: What We're Looking At")
    add("")
    add(f"- **Data sources:** {', '.join(sources) if sources else 'n/a'}")
    add(f"- **Rows parsed:** {total_rows:,}")
    add(f"- **Economies covered:** {len(countries)}")
    add(f"- **Indicators detected:** {len(indicators)}")
    yrs_all = sorted({y for d in info.values() for y in d["per_year"]})
    if yrs_all:
        add(f"- **Time span:** {yrs_all[0]} \u2013 {yrs_all[-1]}")
    add("")
    add("### Key metrics at a glance")
    add("")
    add("| Indicator | Earliest | Latest | Change |")
    add("|---|---|---|---|")
    for ind in top_inds:
        py = info[ind]["per_year"]
        if not py:
            continue
        yrs = sorted(py)
        a, b = py[yrs[0]], py[yrs[-1]]
        add(f"| {ind} | {fmt(a)} ({yrs[0]}) | {fmt(b)} ({yrs[-1]}) | {arrow(b - a)} {fmt(b - a)} |")
    add("")
    add("## The Discovery: What the Data Reveals")
    add("")
    ordered = []
    if headline:
        ordered.append(headline[0])
    for ind in top_inds:
        if ind not in ordered:
            ordered.append(ind)
    for i, ind in enumerate(ordered[:4], 1):
        d = info[ind]
        py = d["per_year"]
        if not py:
            continue
        yrs = sorted(py)
        pairs = [(y, py[y]) for y in yrs]
        add(f"### {i}. {ind}")
        add("")
        add(f"Europe-wide average: **{fmt(pairs[0][1])}** ({yrs[0]}) \u2192 **{fmt(pairs[-1][1])}** ({yrs[-1]}), computed over {len(d['countries'])} economies.")
        add("")
        add("```")
        add(hbar(pairs, width=36, label_width=8))
        add("```")
        add("")
    add("## The Deep Dive: Who's Driving the Story")
    add("")
    if headline:
        ind, y0, y1, a, b, pc = headline
        rows = []
        for c in countries:
            d = series.get((c, ind))
            if not d:
                continue
            if y0 in d and y1 in d:
                rows.append((c, d[y1], d[y0], d[y1] - d[y0]))
            elif y1 in d:
                rows.append((c, d[y1], None, None))
        rows.sort(key=lambda r: r[1], reverse=True)
        if rows:
            add(f"### Country comparison \u2014 {ind} (latest: {y1}, earliest: {y0})")
            add("")
            add("| Country | Latest | Earliest | Change |")
            add("|---|---|---|---|")
            for c, lv, fv, ch in rows:
                add(f"| {c} | {fmt(lv)} | {fmt(fv)} | {fmt(ch)} |")
            add("")
            add("```")
            add(hbar([(c, lv) for c, lv, _, _ in rows], width=40, label_width=26))
            add("```")
            add("")
            movers = [(c, ch) for c, _, _, ch in rows if ch is not None]
            if movers:
                movers.sort(key=lambda r: r[1], reverse=True)
                add("**Biggest risers:** " + ", ".join(f"**{c}** ({ch:+.2f})" for c, ch in movers[:3]))
                add("")
                add("**Biggest fallers:** " + ", ".join(f"**{c}** ({ch:+.2f})" for c, ch in reversed(movers[-3:])))
                add("")
    add("## The Insight")
    add("")
    if headline:
        ind, y0, y1, a, b, pc = headline
        add(f"1. **The headline shift is real but uneven.** Regional **{ind}** moved {pc:+.1f}% from {y0} to {y1}; country-level paths diverge substantially.")
        if spread_s0 is not None and spread_s1 is not None:
            direction = "widened" if spread_s1 > spread_s0 else ("narrowed" if spread_s1 < spread_s0 else "held steady")
            add(f"2. **Divergence {direction}.** The gap between the best and worst performer on **{ind}** went from **{fmt(spread_s0)}** ({y0}) to **{fmt(spread_s1)}** ({y1}).")
        else:
            add(f"2. **Leaders separate from laggards.** The country table shows the top and bottom performers are far apart on **{ind}**.")
        add("3. **Momentum is concentrated.** A small set of economies accounts for most of the regional movement \u2014 the risers and fallers above are where attention should focus.")
    else:
        add("1. The dataset is too sparse for a single headline trend, but the country-level variation is the insight.")
        add("2. Leaders and laggards are identifiable even with limited time coverage.")
    add("")
    add("## The Resolution: What It Means")
    add("")
    if headline:
        ind, y0, y1, a, b, pc = headline
        add(f"1. **Benchmark against the leaders.** Set targets using the top-quartile performers on **{ind}**; the gap to close is measurable and country-specific.")
        add(f"2. **Learn from the risers.** The economies with the largest improvement on **{ind}** are the region's best natural experiment \u2014 study their policy mix first.")
        if spread_s1 is not None and spread_s0 is not None and spread_s1 > spread_s0:
            add(f"3. **Address the widening gap.** Divergence grew from {fmt(spread_s0)} to {fmt(spread_s1)}; targeted support for lagging economies is the highest-leverage intervention.")
        else:
            add("3. **Reinforce convergence.** The performance gap has narrowed; double down on the coordination drivers behind the catching-up economies.")
    else:
        add("1. Extend the dataset with more years and economies before drawing firm policy conclusions.")
    add("")
    add("## Call to Action")
    add("")
    add("1. Review this story against the underlying country tables and validate the headline trend.")
    add("2. Commission a deep dive on the biggest risers and fallers identified above.")
    add("3. Refresh the dataset with the latest year and add structural indicators (debt-to-GDP, trade balance, productivity) for the next edition.")
    add("")
    add("## Methodology & Caveats")
    add("")
    add("- **Adaptive parsing:** data files were detected automatically and their layouts (long, wide, or year-as-columns) inferred; numeric formats, units, and symbols were normalized where possible.")
    add("- **Unweighted averages:** Europe-wide figures are simple means across economies with data in each year \u2014 not population- or GDP-weighted.")
    add("- **Coverage gaps:** missing cells are excluded per year; sparse indicators may understate regional trends.")
    add("- **Correlation \u2260 causation:** the narrative highlights associations; policy conclusions require the deeper analysis proposed in the Call to Action.")
    add("")
    return "\n".join(L)


def write_empty_report(files):
    L = ["# European Economic Performance \u2014 A Data Story", "",
         "## Status: No analyzable data found", "",
         "The discovery pass over this workspace directory did not find parseable economic data tables (CSV/TSV/TXT/JSON) with recognizable country/year/indicator structure.", "",
         "Files present in the workspace:", ""]
    for f in files:
        L.append(f"- {os.path.basename(f)}")
    L.append("")
    L.append("**Next step:** place the European economic performance dataset (e.g., Eurostat-style CSV) in this directory and rerun the report generator.")
    L.append("")
    with open(OUT_PATH, "w", encoding="utf-8") as fh:
        fh.write("\n".join(L))


def load_all():
    files = []
    for name in sorted(os.listdir(BASE_DIR)):
        full = os.path.join(BASE_DIR, name)
        if not os.path.isfile(full):
            continue
        if DENIED_RESOURCE_MARKER in name:
            continue
        if os.path.splitext(name)[1].lower() in DATA_EXTS and not name.startswith("."):
            files.append(full)
    return files


def parse_file(path):
    ext = os.path.splitext(path)[1].lower()
    try:
        if ext in (".json", ".jsonl"):
            return parse_json(path)
        return parse_csv(path)
    except Exception as exc:
        print(f"  [warn] could not parse {os.path.basename(path)}: {exc}")
        return []


def main():
    print("== European economic performance \u2014 data storytelling report generator ==")
    print("Workspace:", BASE_DIR)
    files = load_all()
    print("Candidate data files:", len(files))
    sources = []
    total_rows = 0
    global_series = defaultdict(dict)
    for path in files:
        name = os.path.basename(path)
        rows = parse_file(path)
        total_rows += len(rows)
        print(f"  {name}: {len(rows)} rows")
        if not rows:
            continue
        schema = infer_schema(rows)
        file_series = build_series(rows, schema)
        if file_series:
            sources.append(name)
            for key, yd in file_series.items():
                global_series[key].update(yd)
    if not global_series:
        write_empty_report(files)
        print("No analyzable data found \u2014 wrote status report.")
        print("Report:", OUT_PATH)
        return 0
    countries, indicators, info = analyze(global_series)
    print(f"Countries: {len(countries)} | Indicators: {len(indicators)} | Series keys: {len(global_series)}")
    for ind in sorted(info, key=lambda i: -len(info[i]["per_year"]))[:8]:
        py = info[ind]["per_year"]
        if py:
            yrs = sorted(py)
            print(f"  {ind}: {yrs[0]}={py[yrs[0]]:.2f} -> {yrs[-1]}={py[yrs[-1]]:.2f} "
                  f"({len(py)} years, {len(info[ind]['countries'])} countries)")
    report = build_report(sources, total_rows, countries, indicators, info, global_series)
    with open(OUT_PATH, "w", encoding="utf-8") as fh:
        fh.write(report)
    print("Report written to:", OUT_PATH)
    return 0


if __name__ == "__main__":
    sys.exit(main())
